        // ── Heart Events + Festival AI (v5.0.0) ──
        '初識之誼': 'Budding Friendship',
        '知心好友': 'Trusted Friend',
        '莫逆之交': 'Lifelong Bond',
        '心動時刻': 'Heartbeat Moment',
        '心動事件': 'Heart Event',
        '你發現自己已經把旅人當朋友了。想跟他說說這段時間認識下來的感受,可以提起你們之間的某件小事': "You realize the Traveler has become a friend. You want to share how it's felt getting to know them — maybe bring up a little moment you shared",
        '旅人已是你的知心好友。你想跟他分享一件你從沒告訴過別人的心事或秘密': "The Traveler is now a trusted friend. You want to share something you've never told anyone",
        '旅人是你此生難得的摯友。你想認真地告訴他,他對你有多重要': 'The Traveler is a once-in-a-lifetime friend. You want to tell them, sincerely, how much they mean to you',
        '你發現自己對旅人心動了。你鼓起勇氣,想含蓄地(或依你的性格直白地)透露你的感覺': "You realize you've fallen for the Traveler. You gather your courage to hint at (or, per your personality, outright confess) your feelings",
        '」——邊境鎮的居民。這是一個重要的感情時刻。': '" — a resident of Frontier Town. This is an important emotional moment.',
        '。對象是': '. The person is ',
        '你們的共同回憶：': 'Your shared memories: ',
        '- 繁體中文（台灣用語），2-4句，要真摯、有溫度，符合你的性格': '- 2-4 sentences, sincere and warm, true to your personality',
        '- 可以提到具體的共同回憶或小鎮生活細節': '- You may mention specific shared memories or details of town life',
        '那個...我最近發現,只要看到你走過來,我就會不自覺地笑。你...應該懂我的意思吧?': "So... lately I've noticed that whenever I see you walking over, I can't help but smile. You... know what I mean, right?",
        '跟你說話的時候,時間總是過得特別快。我想...我大概是喜歡上你了。': 'Time always flies when I talk with you. I think... I might have fallen for you.',
        '欸,認真說,自從你來了之後,我覺得這個鎮都不一樣了。有你這個朋友真好。': "Hey, honestly — ever since you came, this town feels different. I'm glad to have you as a friend.",
        '我不太會說這種話,但...謝謝你一直願意聽我說話。這對我來說很重要。': "I'm not good at saying this kind of thing, but... thank you for always listening. It means a lot to me.",
        '我對': 'To ',
        '說出了真心話：': ' I spoke from the heart: ',
        '回應了我的真心話：': ' responded to my honest words: ',
        '我也是。其實我早就想告訴你了': 'Me too. Honestly, I\'ve wanted to tell you for a while',
        '能認識你真的很好,這是我的真心話': "I'm truly glad I got to know you — I mean it",
        '謝謝你...可以讓我想一想嗎?': 'Thank you... could you give me some time to think?',
        '哈哈,突然這麼肉麻我會不好意思啦!': "Haha, going all mushy on me — you're making me blush!",
        '：「': ': "',
