        '帶著一身故事來到邊境鎮,想在這裡重新開始。': 'Came to Frontier Town with a lifetime of stories, hoping to start over.',
        '土生土長的鎮民,對這片土地有說不完的感情。': 'Born and raised here, with endless affection for this land.',
        '曾在遠方闖蕩多年,如今只想找個安穩的落腳處。': 'Roamed far away for years; now just wants a settled place to land.',
        '沉默寡言,但只要熟了就會發現一顆熱心腸。': 'Quiet and reserved, but a warm heart shows once you get to know them.',
        '心裡藏著一個沒說出口的夢,也藏著一個沒說出口的人。': 'Holds an unspoken dream, and an unspoken someone.',
        '嘴上不饒人,做起事來卻比誰都認真。': 'Sharp-tongued, but works harder than anyone.',
        '走到哪都能交到朋友,也總在不經意間牽動誰的心。': 'Makes friends everywhere, and unwittingly tugs at someone\'s heart.',
