        '本機': 'local',
        ' 訪客）': ' visiting)',
        '海風鎮的故事': 'Stories of Seabreeze',
        '這座漁村沒有既定的劇本——阿潮的暗戀、石叔與燈爺的舊怨、雲姨未說完的往事，都在日常裡自己發生。多跟大家聊聊，故事會找上你。': "This fishing village has no script — Achao's crush, the old grudge between Shishu and Grandpa Deng, Aunt Yun's unfinished past all unfold on their own. Talk to people, and the stories will find you.",

        // ── v5.58.1 馬車切鎮修復 ──
        '切換城鎮失敗：找不到該城鎮的存檔。': "Failed to switch towns: that town's save could not be found.",
        '找不到目的地的存檔': "destination save not found",

        // ── v5.58.0 海風鎮本來就存在+親緣網 ──
        '新城鎮建立中，原本的城鎮會先自動儲存…': 'Founding new town — your current town is being saved first…',
        '處理中…': 'Working…',
        '請稍候，不要重新整理頁面': 'Please wait — do not reload the page',
        '已建立': ' founded',
        '原本的城鎮已自動儲存，「城鎮列表」隨時可切換，兩鎮並存': 'Your previous town was saved automatically — switch anytime via the Towns list; both coexist',
        '📯 沿海道路修復完成，往海風鎮的馬車恢復通行！': '📯 The coastal road is repaired — coaches to Seabreeze are running again!',
        '道路重通！': 'The road is open!',
        '通往漁村「海風鎮」的沿海道路修好了——去東邊的馬車站就能搭車拜訪，兩鎮的村民也會開始互相作客': 'The coastal road to the fishing village of Seabreeze is repaired — catch a coach at the station to the east; villagers of both towns will start visiting each other too',
        '車伕靠在車轅上打盹：「往海風鎮的沿海道路還封著呢——聽說鎮子發展起來，就會組修路隊把路打通。急的話，先跟商隊買點那邊的魚乾解解饞吧。」': 'The coachman dozes against the shaft: "The coastal road to Seabreeze is still blocked. Word is once this town grows, a repair crew will open it up. Meanwhile, the caravans sell dried fish from over there."',
        '姑婆又從海風鎮寄魚乾來了，她醃的魚誰都比不上。': "Great-aunt sent dried fish from Seabreeze again — no one cures fish like her.",
        '我這手醃魚的功夫，是海風鎮的姑婆海嬤教的。': 'My fish-curing craft came from great-aunt Hai-ma in Seabreeze.',
        '老石那傢伙去海邊曬鹽也二十年了，礦上的日子他還記得嗎。': "Old Shi's been drying salt by the sea for twenty years — does he still remember the mines?",
        '當年跟老石同一條坑道，現在一個挖礦一個曬鹽。': 'Old Shi and I shared a mine shaft once — now one digs ore, one dries salt.',
        '浪叔的船這批貨怎麼還沒到，別又在哪個港口喝茫了。': "Uncle Lang's shipment is late again — better not be drunk in some port.",
        '我店裡的異國貨，一半是海風鎮浪叔的船捎回來的。': "Half my exotic goods come on Uncle Lang's boat from Seabreeze.",
        '在海味居駐唱那陣子，掌杓姑娘的海鮮麵配我的歌，絕了。': "Those nights singing at the Sea Flavor Inn — her seafood noodles with my songs, perfection.",
        '那首關於海的歌，是在海風鎮寫的。': 'That song about the sea? I wrote it in Seabreeze.',
        '燈爺的信裡說，航海日誌裡有段記載跟遺跡對得上…': "Old Deng's letter says a passage in his nautical logs matches the ruins…",
        '海風鎮的燈爺是我通信多年的筆友，他懂的比書還多。': 'Old Deng the lighthouse keeper has been my pen pal for years — he knows more than any book.',
        '同期的阿汐在海風鎮當醫師，海女出身的她潛得比誰都深。': 'A-Xi from my class practices in Seabreeze — a diver-born doctor who goes deeper than anyone.',
        '好想跟阿汐當面討論那個病例，可惜路還封著，只能寫信。': "I wish I could discuss that case with A-Xi in person, but the road's still closed — letters it is.",
        '邊境鎮的姪孫女王麗，醃魚的手藝是我教的，不知道長進了沒。': 'My grandniece Wang Li in Frontier Town — I taught her to cure fish. Has she improved?',
        '礦上的老吳還在挖嗎…當年說好老了一起釣魚的。': 'Is old Wu still digging? We promised to fish together when we got old.',
        '邊境鎮的趙老闆娘又下了一批訂單，這趟得跑快點。': 'Boss Zhao in Frontier Town placed another order — better make this run quick.',
        '那個彈吉他的流浪商人，唱的那首海歌我現在還會哼。': 'That wandering trader with the guitar — I still hum his sea song.',
        '邊境鎮那位孫姑娘的信又到了，她問的遺跡我日誌裡正好有記載。': "Another letter from Miss Sun in Frontier Town — my logs happen to mention the ruins she asks about.",
        '同期的林美在邊境鎮行醫，她的信裡總夾著新藥方。': 'Lin Mei from my class practices in Frontier Town — her letters always carry new prescriptions.',

